import { Icon } from '@cetus/ui-kit'
import { cancelBubble } from '@cetus/utils'
import { Box, Button, Flex, FlexProps, HStack, Menu, MenuButton, MenuButtonProps, MenuList, Text, VStack } from '@chakra-ui/react'
import { useState } from 'react'

export type SortDropType = {
  label: string
  value: string
}

const SortDropBlock = ({
  sortText,
  minW,
  iconSize = '40px',
  wrapStyle = {},
  currentSort,
  onSortByChange,
  sortByList,
  xlinkHref = '',
  iconBoxStyle,
  iconOnClick
}: {
  sortText: string
  minW?: string
  iconSize?: string
  wrapStyle?: MenuButtonProps
  currentSort: SortDropType
  onSortByChange: (type: SortDropType) => void
  sortByList: SortDropType[]
  xlinkHref?: string
  iconBoxStyle?: FlexProps
  iconOnClick?: () => void
}) => {
  const [isOpen, setIsOpen] = useState(false)

  const baseWidth = minW || 'unset'
  const totalWidth = minW && xlinkHref ? `calc(${minW} + ${iconSize} + 12px)` : baseWidth

  console.log('🚀 ~ totalWidth:', totalWidth)
  return (
    <Menu isLazy isOpen={isOpen} placement="bottom-end" onClose={() => setIsOpen(false)}>
      <HStack
        w={totalWidth}
        minW={totalWidth}
        gap="12px"
        bg="bg_secondary"
        borderRadius={{ base: '8px', lg: '12px' }}
        border="1px solid"
        borderColor="border"
        h={iconSize}
        p="0 4px 0 10px"
      >
        {xlinkHref && (
          <Flex
            w={iconSize}
            h={iconSize}
            minW={iconSize}
            borderRight="1px solid"
            borderColor="border"
            borderRadius={{ base: '8px', lg: '12px' }}
            justify="center"
            align="center"
            ml="-10px"
            {...iconBoxStyle}
          >
            <Icon
              xlinkHref={xlinkHref}
              variant="gray"
              onClick={e => {
                cancelBubble(e)
                setIsOpen(false)
                iconOnClick?.()
              }}
            />
          </Flex>
        )}

        <MenuButton
          as={Button}
          w={baseWidth}
          h="38px"
          p="0"
          // pr="10px"
          bg="bg_secondary"
          isActive={isOpen}
          borderRadius={{ base: '8px', lg: '12px' }}
          sx={{
            _hover: {
              bg: 'bg_secondary',
              '.drop-icon': {
                svg: {
                  fill: 'text_caption'
                }
              }
            },
            _active: {
              bg: 'bg_secondary'
            }
          }}
          {...wrapStyle}
          onClick={() => setIsOpen(true)}
        >
          <HStack align="center" justifyContent="space-between">
            <HStack gap="8px">
              <Text color="text_caption" fontSize={{ base: '12px', lg: '14px' }}>
                {sortText}
              </Text>
            </HStack>
            <HStack gap="8px">
              <Text color="text_caption" fontSize={{ base: '12px', lg: '14px' }}>
                {currentSort?.label}
              </Text>
              <Box className="drop-icon">
                <Icon
                  svgW="16px"
                  xlinkHref="#icon-icon_arrow"
                  variant="gray"
                  transition="transform 0.5s"
                  transform={isOpen ? 'rotate(180deg)' : 'rotate(0deg)'}
                />
              </Box>
            </HStack>
          </HStack>
        </MenuButton>
      </HStack>

      <MenuList
        p="4px"
        opacity="1"
        overflow="hidden"
        minW={totalWidth} // ✅ 下拉菜单和容器一致宽
        mr="-5px"
      >
        <VStack w="100%" gap="4px">
          {sortByList.map(item => (
            <Text
              key={item.value}
              w="100%"
              h="36px"
              lineHeight="36px"
              textAlign="center"
              borderRadius="8px"
              cursor="pointer"
              fontSize={{ base: '12px', lg: '14px' }}
              color="text_caption"
              bg={currentSort?.value === item.value ? 'menu_item_bg' : 'none'}
              sx={{
                _hover: {
                  bg: 'menu_item_bg'
                }
              }}
              onClick={() => {
                onSortByChange(item)
                setIsOpen(false)
              }}
            >
              {item.label}
            </Text>
          ))}
        </VStack>
      </MenuList>
    </Menu>
  )
}

export default SortDropBlock
